// skills/SKILLS_INDEX.json is generated by `prebuild`; this fails when a
// SKILL.md changed without regenerating it (run: node scripts/build-skills-index.mjs).
import fs from "node:fs";
import path from "node:path";
import { describe, it, expect } from "vitest";
import { buildSkillsIndex, parseFrontmatter } from "../../scripts/build-skills-index.mjs";

const root = path.resolve(__dirname, "../..");

describe("skills index", () => {
  it("matches the skills/ folder", () => {
    const committed = JSON.parse(fs.readFileSync(path.join(root, "skills/SKILLS_INDEX.json"), "utf8"));
    expect(committed).toEqual(buildSkillsIndex(path.join(root, "skills")));
  });

  it("parses frontmatter name and description", () => {
    expect(parseFrontmatter("---\nname: x\ndescription: \"Does y: z\"\n---\n# body")).toEqual({ name: "x", description: "Does y: z" });
    expect(parseFrontmatter("# no frontmatter")).toEqual({});
  });
});
